#include "KS/SRC/ks/wave_shared.h"
#include "KS/SRC/vector3d_shared.h"

typedef unsigned int u_int;
#define MAX_SPRAY_PTS 25
#define MAX_TRAIL_NODES 30

class kellyslater_controller;

class Random
{
  unsigned int rand_next;
  unsigned int NextRand()
  {
    rand_next = rand_next*1103515245 + 12345;
    return (rand_next>>16)&32767;
  }
public:
  int rand()
  {
    unsigned int r = NextRand();
    return r;
  }
};
extern Random *g_random_ptr;

struct surface_point_t
{
  WavePositionHint hint;
  WaveVelocityHint vhint;
  vector3d pos;
  vector3d norm;
  WaveRegionEnum region;
  u_int vvalid;
};

struct trail_node_t
{
  u_int valid;
  float age;
  float uv;
  surface_point_t pnt1;
  surface_point_t pnt2;
  surface_point_t pnt3;
};

struct spray_control_t
{
  vector3d current __attribute__((aligned(16)));
  vector3d start __attribute__((aligned(16)));
  vector3d *trailpt;
  trail_node_t *trail_node;
  vector3d vel;
  float seed;
  float age;
  float life;
  int valid;
};

struct spray_params_t
{
  spray_control_t control_points_a[MAX_SPRAY_PTS];
  spray_control_t control_points_b[MAX_SPRAY_PTS];
  int num_control_points_a;
  int num_control_points_b;
  float last_apow;
  float last_bpow;
  vector3d lastpointa;
  vector3d lastpointb;
  float extra_splash_power[2];
  vector3d last_vec;
  float floater_interval;
  float airdrops_interval;
  float left_hand_interval;
  float right_hand_interval;
};

class trail
{
public:
  virtual ~trail();
  void initialize(float sample_rate, float life, bool extra, kellyslater_controller *owner);
protected:
  bool valid;
  u_int my_index;
  float my_life;
  float my_sample_rate;
  float my_last_sample;
  u_int my_total_nodes;
  trail_node_t my_trail_data[MAX_TRAIL_NODES];
  bool my_extra;
  float my_lastmag1;
  float my_lastmag2;
  kellyslater_controller *my_owner;
  spray_params_t *my_spray;
};

void trail::initialize (float sample_rate, float life, bool extra, kellyslater_controller *owner)
{
  u_int i;

  valid = true;

  // NGL only supports strips of up to 36 vertexes
//  if (sample_rate * life > 17)
//    life = 17 / sample_rate;

  my_sample_rate = sample_rate;
  my_total_nodes = MAX_TRAIL_NODES;

  for (i = 0; i < my_total_nodes; i++)
  {
    my_trail_data[i].valid = 0;
    my_trail_data[i].pnt1.vvalid = 0;
    my_trail_data[i].pnt2.vvalid = 0;
    my_trail_data[i].pnt3.vvalid = 0;
  }

  my_extra = extra;
  my_life = life;
  my_last_sample = 0;
  my_index = 0;
  my_lastmag1 = 0;
  my_lastmag2 = 0;

  my_owner = owner;

  if (my_owner)
  {
    my_spray->last_apow = 0;
    my_spray->last_bpow = 0;
    my_spray->num_control_points_a = 0;
    my_spray->num_control_points_b = 0;
    my_spray->floater_interval = 0;
    my_spray->airdrops_interval = 0;
    my_spray->left_hand_interval = 0;
    my_spray->right_hand_interval = 0;
    my_spray->extra_splash_power[0] = 0;
    my_spray->extra_splash_power[1] = 0;

    for (i = 0; i < MAX_SPRAY_PTS; i++)
    {
      my_spray->control_points_a[i].seed = (g_random_ptr->rand()<<2)%0x7fffffff;
      my_spray->control_points_b[i].seed = (g_random_ptr->rand()<<2)%0x7fffffff;
      my_spray->control_points_a[i].valid = false;
      my_spray->control_points_b[i].valid = false;
    }
  }
}
